class Solution { public: int maxSumMinProduct(vector<int>& nums){int n=nums.size();vector<long long> prefix(n+1);for(int i=0;i<n;++i)prefix[i+1]=prefix[i]+nums[i];vector<int> left(n),right(n),stack;for(int i=0;i<n;++i){while(!stack.empty()&&nums[stack.back()]>=nums[i])stack.pop_back();left[i]=stack.empty()?-1:stack.back();stack.push_back(i);}stack.clear();for(int i=n-1;i>=0;--i){while(!stack.empty()&&nums[stack.back()]>=nums[i])stack.pop_back();right[i]=stack.empty()?n:stack.back();stack.push_back(i);}long long best=0;for(int i=0;i<n;++i)best=max(best,(prefix[right[i]]-prefix[left[i]+1])*nums[i]);return best%1000000007;} };
